# -*- coding: utf-8 -*-
"""R75 S2 blind predictions: B04,B05,B06 (60 cases). Writes only own ids."""
import json, pathlib
BASE = pathlib.Path('/home/hatch/workspace/divination/benchmark/phase3')
OUT = BASE/'runs/round75/predictions'
BATCHES = json.loads((BASE/'runs/round75/batches.json').read_text(encoding='utf-8'))
MY = BATCHES['B04']+BATCHES['B05']+BATCHES['B06']
assert len(MY)==60 and len(set(MY))==60
F=lambda: {"changed_main":False,"reserve_used":False,"disputed":False,"reason":""}
def T(**kw):
    d=F(); d.update(kw); return d
DATA=[]
def add(cid, txt, basis, conf, trig=None):
    DATA.append({"case_id":cid,"prediction_text":txt,"basis":basis,"confidence":conf,
                 "trigger": trig if trig is not None else F()})
def flush(expected_ids):
    got=[d["case_id"] for d in DATA]
    assert got==expected_ids, (got, expected_ids)
    for d in DATA:
        (OUT/f"{d['case_id']}.json").write_text(json.dumps(d,ensure_ascii=False,indent=1),encoding='utf-8')
    print("wrote",len(DATA))
    DATA.clear()

